#!/usr/bin/env python3
from __future__ import annotations
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; DATA=ROOT/'data'; SITE=ROOT/'site'; BASE='/dc-public-realm'
def load(n): return json.loads((DATA/n).read_text(encoding='utf-8'))
def esc(x): return html.escape(str(x))
E={x['entity_id']:x for x in load('entities.json')['entities']}; A={x['assertion_id']:x for x in load('assertions.json')['assertions']}; S={x['source_id']:x for x in load('sources.json')['sources']}; evidence=load('assertion-evidence.json')['assertion_evidence']; tasks=[x for x in load('research-tasks.json')['tasks'] if x.get('object_entity_id')=='OBJ-0001']; MODES={x['assertion_id']:x['mode'] for x in load('claim-modes.json')['claim_modes']}; MODE_LABEL={'DOCUMENTARY_FACT':'Historical record','ATTRIBUTION_RECONSTRUCTION':'Attribution','INTERPRETATION':'Interpretation'}; EV={}
for e in evidence: EV.setdefault(e['assertion_id'],[]).append(e)
ROLE={'PRIMARY_SUPPORT':'Main source','CORROBORATION':'Additional source','QUALIFIES':'Qualification','CONTRADICTS':'Differing record','IMAGE_EVIDENCE':'Image evidence'}
CLAIMS=[('A-0001','Gift','Congressional records describe the memorial as a gift from the people of Uruguay.'),('A-0002','Custody','The National Park Service is recorded as the current custodian.'),('A-0004','Relationship to the earlier monument','Uruguay’s heritage record identifies the Washington bronze as a copy of the 1898 Artigas monument at San José de Mayo. The Smithsonian inventory describes the Washington work as a recast and places the predecessor in Montevideo. The records differ on the predecessor and object relationship.'),('A-0005','Casting location','The Smithsonian inventory associates the Washington recast with Montevideo, Uruguay. The foundry is not identified in the sources reviewed.'),('A-0005B','Approximate recast date','The Smithsonian inventory dates the Washington recast to approximately the early 1940s.')]
def slink(s): return f'<a href="{esc(s["url"])}">{esc(s["title"])}</a>'
def evidence_label(evs):
 pubs={e.get('source_id') for e in evs if e.get('source_id')}; n=len(pubs)
 if any(e.get('evidence_role')=='CONTRADICTS' for e in evs): return f'{n} publications · differing records'
 pos=[e for e in evs if e.get('evidence_role') in {'PRIMARY_SUPPORT','CORROBORATION','IMAGE_EVIDENCE'}]
 if len(pos)>1 and any(e.get('claim_origin')=='UNKNOWN' for e in pos): return f'{n} publications · source history incomplete'
 return f'{n} publication'+('s' if n!=1 else '')
def genealogy(aid):
 rows=[]
 for e in EV.get(aid,[]):
  s=S[e['source_id']]; origin=e.get('claim_origin','UNKNOWN'); parents=e.get('inherits_claim_from_source_ids',[])
  if origin=='ORIGINAL_TO_SOURCE': status='Recorded as originating in this source.'
  elif origin in {'INHERITED','MIXED'} and parents: status='Derived from: '+', '.join(parents)
  else: status='The source for this statement has not been established.'
  rows.append(f'<li><strong>{esc(s["title"])}</strong><br><span class="small">{esc(status)}</span></li>')
 extra=''
 if aid=='A-0004': extra='''<div class="genealogy-note"><strong>Research note.</strong><p class="small">The Smithsonian inventory cites Goode (1974), National Park Service material (1985), Michael Richman’s 1967–69 research, and a 1991 Smithsonian research project. The public catalog does not assign those references to individual statements about the recast or predecessor. The source history for those statements remains under review.</p><p class="small"><a href="https://github.com/danielastone/dc-public-realm/issues/19">Goode</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/20">Richman</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/21">NPS 1985</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/22">Smithsonian 1991</a></p></div>'''
 return f'<details class="genealogy"><summary>Source history</summary><ul>{"".join(rows)}</ul>{extra}</details>'
def epanel(aid):
 rows=[]
 for e in EV.get(aid,[]):
  s=S[e['source_id']]; note=e.get('evidence_note',''); rows.append(f'<div class="source-row"><strong>{esc(ROLE.get(e["evidence_role"],e["evidence_role"]))}</strong> · {slink(s)}<div class="small">{esc(e.get("locator","Record"))}{" — "+esc(note) if note else ""}</div></div>')
 return f'<details class="evidence"><summary>Sources <span>{esc(evidence_label(EV.get(aid,[])))}</span></summary>{"".join(rows)}{genealogy(aid)}<p class="small"><a href="#provenance-{esc(aid)}">Technical record</a></p></details>'
def claim(aid,title,text):
 mode=MODE_LABEL.get(MODES.get(aid),'Research claim'); return f'<article class="claim"><div class="eyebrow">{esc(mode)}</div><h3>{esc(title)}</h3><p>{esc(text)} <a class="cite" href="#provenance-{esc(aid)}">[{esc(aid.replace("A-",""))}]</a></p>{epanel(aid)}</article>'
HOOKS={'URY-ART-001':('Diplomatic correspondence, 1947–1951','Correspondence may document authorization, casting, shipment, or contemporary descriptions of the Washington statue.','A folder citation, scan, archival reference, or repository contact.'),'URY-ART-002':('El Día, “Monumento a Artigas en Washington,” 1949','The pre-dedication article may contain contemporary information on production, financing, shipment, or installation.','The complete article with continuation pages, captions, credits, date, and page number.'),'URY-ART-003':('Blanes and Costa records, 1894–1896','Uruguay’s 2004 heritage resolution summarizes an 1894 commission and an 1896 Dante Costa contract. The underlying records have not yet been examined.','An archival citation, catalog record, image, or authoritative reproduction of either record.')}
def question(t):
 title,plain,quick=HOOKS.get(t['task_id'],(t['title'],t['research_gap'],t['high_value_result'])); return f'<article class="question"><div class="eyebrow">RESEARCH REQUEST</div><h3>{esc(title)}</h3><p>{esc(plain)}</p><p><strong>Requested material:</strong> {esc(quick)}</p><a class="button" href="{BASE}/tasks/{esc(t["task_id"].lower())}/">Research task</a><details><summary>Research notes</summary><p>{esc(t["research_gap"])}</p><p class="small"><strong>Evidence requirement:</strong> {esc(t["critical_rule"])}</p></details></article>'
LINEAGE_HOOKS=[('Goode 1974, pp. 443–444','The Artigas entry may identify sources used before later NPS and Smithsonian records.','Page scan, transcription, or citations from the Artigas entry.','https://github.com/danielastone/dc-public-realm/issues/19'),('Michael Richman research, 1967–69','The Smithsonian inventory cites this research without identifying which statements derive from it.','Collection or folder citation, finding aid, archive contact, or relevant notes.','https://github.com/danielastone/dc-public-realm/issues/20'),('National Park Service record, 1985','The Smithsonian inventory cites an NPS source whose claim-level contribution is not identified.','Exact title, catalog identifier, scan, or archival location.','https://github.com/danielastone/dc-public-realm/issues/21'),('Smithsonian research project, 1991','The public record does not indicate which materials were examined by the 1991 project.','Project-file citation, finding-aid entry, archive contact, or description of the materials examined.','https://github.com/danielastone/dc-public-realm/issues/22')]
def lineage_hook(x):
 title,why,quick,url=x; return f'<article class="question lineage"><div class="eyebrow">SOURCE RESEARCH</div><h3>{esc(title)}</h3><p>{esc(why)}</p><p><strong>Requested material:</strong> {esc(quick)}</p><a class="button" href="{esc(url)}">Research task</a></article>'
def prov(aid):
 a=A[aid]; rows=[]
 for e in EV.get(aid,[]):
  s=S[e['source_id']]; inh=', '.join(e.get('inherits_claim_from_source_ids',[])) or 'none recorded'; rows.append(f'<li><strong>{esc(e["source_id"])}</strong> — {esc(s["title"])}<br><span class="small">role={esc(e["evidence_role"])} · authority_fit={esc(e.get("authority_fit"))} · proximity={esc(e.get("proximity"))} · claim_origin={esc(e.get("claim_origin"))} · inherited_from={esc(inh)}</span></li>')
 return f'<details class="technical" id="provenance-{esc(aid)}"><summary>{esc(aid)} · {esc(a["predicate"])}</summary><ul>{"".join(rows)}</ul></details>'
roles=[]
for aid,label in [('A-0007A','Commission entrusted to'),('A-0007B','Sketch developed by'),('A-0007C','Modeled and cast by')]:
 obj=E.get(A[aid].get('object_entity_id'),{}).get('canonical_name','Unresolved'); mode=MODE_LABEL.get(MODES.get(aid),'Research claim'); roles.append(f'<li><span class="small">{esc(mode)}</span><br><strong>{esc(label)}:</strong> {esc(obj)}{epanel(aid)}</li>')
sids=[]
for aid in [x[0] for x in CLAIMS]+['A-0007A','A-0007B','A-0007C']:
 for e in EV.get(aid,[]):
  if e['source_id'] not in sids: sids.append(e['source_id'])
source_cards=''.join(f'<li>{slink(S[sid])}<br><span class="small">{esc(S[sid].get("publisher_or_creator",""))} · {esc(S[sid].get("authority_scope",""))}</span></li>' for sid in sids)
css='''<style>:root{--fg:#171717;--muted:#606060;--line:#d9d9d4;--soft:#f7f7f3;--accent:#5a3d16}*{box-sizing:border-box}body{margin:0;color:var(--fg);font-family:ui-serif,Georgia,serif;line-height:1.62}header,main,footer{max-width:900px;margin:auto;padding:1.2rem}header{border-bottom:1px solid var(--line)}nav a{margin-right:1rem;color:inherit}.eyebrow,.small,summary span{font-family:ui-sans-serif,system-ui,sans-serif;color:var(--muted);font-size:.86rem}.eyebrow{letter-spacing:.06em}h1{font-size:clamp(2.3rem,7vw,4.7rem);line-height:1;margin:.3rem 0 1rem}h2{margin-top:3rem;border-bottom:1px solid var(--line);padding-bottom:.35rem}.lede{font-size:1.25rem;max-width:760px}.claim,.question{margin:1.4rem 0}.claim h3,.question h3{margin-bottom:.25rem}.cite{text-decoration:none;font-family:ui-sans-serif,system-ui,sans-serif;font-size:.75rem;vertical-align:super}.evidence,.technical{background:var(--soft);border:1px solid var(--line);padding:.65rem .8rem;margin:.6rem 0}.evidence summary,.technical summary,.genealogy summary{cursor:pointer;font-family:ui-sans-serif,system-ui,sans-serif;font-weight:650}.genealogy{margin:.75rem 0;padding:.6rem .75rem;border-left:3px solid var(--line);background:white}.genealogy li{margin:.55rem 0}.genealogy-note{margin-top:.8rem;padding:.65rem;background:var(--soft)}.evidence summary span{float:right;font-weight:400}.source-row{padding:.6rem 0;border-top:1px solid var(--line)}.source-row:first-of-type{margin-top:.5rem}.question{border-left:4px solid var(--accent);padding:1rem;background:#fffdf8}.question details{margin-top:.75rem}.subhead{margin-top:2.5rem}.question summary{cursor:pointer;font-family:ui-sans-serif,system-ui,sans-serif;font-weight:650}.button{display:inline-block;border:1px solid var(--fg);padding:.45rem .75rem;color:inherit;text-decoration:none}.tabs{position:sticky;top:0;background:white;border-bottom:1px solid var(--line);padding:.7rem 0;z-index:2}.tabs a{margin-right:1rem;font-family:ui-sans-serif,system-ui,sans-serif;font-size:.9rem;color:inherit}.sources li,.technical li{margin:.7rem 0}footer{border-top:1px solid var(--line);margin-top:3rem;color:var(--muted)}@media(max-width:600px){.evidence summary span{float:none;display:block;margin-top:.2rem}.tabs{position:static}}</style>'''
body=f'''<div class="eyebrow">OBJ-0001 · URUGUAY</div><h1>José Gervasio Artigas Memorial</h1><p class="lede">Public monument in Washington, D.C. Records reviewed for this catalog connect the bronze to an earlier monument to Artigas in Uruguay, but differ on the identity of the predecessor and the nature of the Washington version.</p><nav class="tabs"><a href="#description">Description</a><a href="#history">History</a><a href="#attribution">Attribution</a><a href="#sources">References</a><a href="#research">Research notes</a><a href="#provenance">Record data</a></nav><section id="description"><h2>Description</h2><p>Monument to José Gervasio Artigas in Washington, D.C. Congressional records describe it as a gift from the people of Uruguay. The National Park Service is recorded as the current custodian.</p></section><section id="history"><h2>Object history</h2>{''.join(claim(*x) for x in CLAIMS)}</section><section id="attribution"><h2>Attribution</h2><p>Uruguay's heritage resolution records separate roles in the development of the earlier San José monument:</p><ul>{''.join(roles)}</ul><p class="small">The sources reviewed do not identify the foundry or caster of the Washington bronze.</p></section><section id="sources"><h2>References</h2><ul class="sources">{source_cards}</ul></section><section id="research"><h2>Research notes</h2><p>Cataloging is ongoing. The following records have been identified for further research.</p>{''.join(question(t) for t in tasks)}<h3 class="subhead">Sources cited by the Smithsonian inventory</h3>{''.join(lineage_hook(x) for x in LINEAGE_HOOKS)}</section><section id="provenance"><h2>Record data</h2><p class="small">Claim identifiers and source relationships used in this catalog record.</p>{''.join(prov(aid) for aid in [x[0] for x in CLAIMS]+['A-0007A','A-0007B','A-0007C'])}</section>'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>José Gervasio Artigas Memorial — Diplomatic Gifts in Washington</title>{css}</head><body><header><a href="{BASE}/">Diplomatic Gifts in Washington</a> <span class="small">/ Artigas</span></header><main>{body}</main><footer>Cataloging and source review are ongoing. Records may be revised as additional documentation is examined.</footer></body></html>'''
out=SITE/'objects'/'jose-gervasio-artigas'/'index.html'; out.parent.mkdir(parents=True,exist_ok=True); out.write_text(page,encoding='utf-8'); print('Wrote',out)
